/** Delta sync routes — thin edge adapter mirroring backend/src/routes/sync.ts.
 *
 * All the logic lives in `shared/services/sync.ts` (generated by
 * `npm run sync:edge`), so this file is just the Hono binding. Deliberately not
 * entitlement-gated: see the backend file for why sync is an auth boundary and
 * not a paywall. */
import { Hono } from "hono";
import { z } from "zod";
import { makeAuthenticate, readJson, requireUser, type AppEnv, type Deps } from "../deps.ts";
import { readEntitlement } from "../shared/services/entitlement.ts";
import { settleOpenPayments } from "../shared/services/payment-flow.ts";
import {
  MAX_PUSH_RECORDS,
  PULL_PAGE_SIZE,
  pullRecords,
  pushRecords,
  type PushRecord,
} from "../shared/services/sync.ts";

const pushBody = z.object({
  records: z
    .array(
      z.object({
        kind: z.string().min(1).max(32),
        id: z.string().min(1).max(128),
        data: z.unknown(),
        updatedAt: z.number().int().nonnegative(),
        deleted: z.boolean(),
      }),
    )
    .max(MAX_PUSH_RECORDS),
});

const pullQuery = z.object({
  cursor: z.coerce.number().int().nonnegative().default(0),
  limit: z.coerce.number().int().positive().max(PULL_PAGE_SIZE).default(PULL_PAGE_SIZE),
});

export function syncRoutes(deps: Deps) {
  const { db, psp } = deps;
  const now = () => new Date(deps.now());
  const auth = makeAuthenticate(deps);
  const r = new Hono<AppEnv>();

  r.post("/sync/push", auth, async (c) => {
    if (!deps.env.LEGACY_PERSONAL_SYNC_ENABLED) {
      return c.json(
        {
          error: "sync_disabled",
          message: "Personal data sync is retired; data remains on the user's device.",
        },
        410,
      );
    }
    const user = requireUser(c);
    const { records } = pushBody.parse(await readJson(c));
    return c.json(await pushRecords(db, user.id, records as PushRecord[], now()));
  });

  // The last page carries the entitlement too, so the app does not spend a
  // second invocation on `GET /subscriptions/me` every time it opens. See the
  // Fastify twin for the reasoning; on the free tier invocations are the ceiling.
  r.get("/sync/pull", auth, async (c) => {
    if (!deps.env.LEGACY_PERSONAL_SYNC_ENABLED) {
      return c.json(
        {
          error: "sync_disabled",
          message: "Personal data sync is retired; data remains on the user's device.",
        },
        410,
      );
    }
    const user = requireUser(c);
    const { cursor, limit } = pullQuery.parse({
      cursor: c.req.query("cursor"),
      limit: c.req.query("limit"),
    });
    const page = await pullRecords(db, user.id, cursor, limit);
    if (page.hasMore) return c.json(page);
    // Finish any payment whose gateway callback never made it back — see the
    // Fastify twin. A VPN-routed browser drops that redirect often enough that
    // without this the money moves and nothing is granted.
    await settleOpenPayments(db, psp, user.id, now());
    return c.json({ ...page, entitlement: await readEntitlement(db, user.id, now()) });
  });

  return r;
}
